INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(28423537, 'Archfiend Emperor, the First Lord of Horror', '战栗的凶皇－始祖恶魔', '戦慄の凶皇－ジェネシス・デーモン', 'Effect Monster', 'Fiend', 'DARK', 8, 3000, 2000, '①：这张卡可以不用解放作召唤。 ②：这张卡的①的方法召唤的这张卡的原本的攻击力·守备力变成一半，结束阶段破坏。 ③：只要这张卡在怪兽区域存在，自己不是恶魔族怪兽不能特殊召唤。 ④：1回合1次，把自己的手卡·墓地1张「恶魔」卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(31766317, 'Archfiend Empress', '地狱女帝恶魔', 'ヘル・エンプレス・デーモン', 'Effect Monster', 'Fiend', 'DARK', 8, 2900, 2100, '这张卡以外的场上表侧表示存在的恶魔族·暗属性怪兽1只被破坏的场合，可以作为代替把自己墓地存在的1只恶魔族·暗属性怪兽从游戏中除外。此外，场上存在的这张卡被破坏送去墓地时，可以选择「地狱女帝恶魔」以外的自己墓地存在的1只恶魔族·暗属性·6星以上的怪兽特殊召唤。'),
(48675364, 'Archfiend General', '将军恶魔', 'ジェネラルデーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 2100, 800, '把这张卡从手卡丢弃去墓地。从卡组把1张「万魔殿-恶魔的巢窟-」加入手卡。场上没有「万魔殿-恶魔的巢窟-」存在的场合，场上的这张卡破坏。'),
(84341431, 'Archfiend Giant', '恶魔的巨神', 'デーモンの巨神', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, 1600, '①：怪兽区域的这张卡被效果破坏的场合，可以作为代替而支付500基本分。这个效果只在这张卡在场上表侧表示存在能使用1次。 ②：这张卡被效果破坏送去墓地的场合才能发动。从手卡把1只「恶魔」怪兽特殊召唤。'),
(66540884, 'Archfiend Heiress', '诡计恶魔', 'トリック・デーモン', 'Effect Monster', 'Fiend', 'DARK', 3, 1000, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡被效果送去墓地的场合或者被战斗破坏送去墓地的场合才能发动。从卡组把「诡计恶魔」以外的1张「恶魔」卡加入手卡。'),
(14430063, 'Archfiend Interceptor', '拦截恶魔', 'インターセプト・デーモン', 'Effect Monster', 'Fiend', 'DARK', 4, 1400, 1600, '只要这张卡在自己场上表侧攻击表示存在，对方怪兽的攻击宣言时，给与对方基本分500分伤害。'),
(75889523, 'Archfiend Marmot of Nefariousness', '恶魔啃食者', 'デーモン・ビーバー', 'Normal Monster', 'Beast', 'EARTH', 2, 400, 600, '拥有恶魔角与翅膀的海狸。投掷橡实果进行攻击。'),
(7622360, 'Archfiend Matador', '恶魔斗牛士', 'デーモンズ・マタドール', 'Ritual Effect Monster', 'Warrior', 'DARK', 6, NULL, NULL, '「斗牛士降临的仪式 暗之入场式」降临 这个卡名的①的效果1回合只能使用1次。 ①：这张卡仪式召唤的场合才能发动。从卡组把「恶魔斗牛士」以外的2张「恶魔」卡加入手卡。这个回合，这张卡不能攻击。 ②：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ③：这张卡和怪兽进行战斗的伤害计算后发动。那只怪兽破坏，给与对方1000伤害。'),
(15150371, 'Archfiend Mirror', '恶魔之镜', '悪魔の鏡', 'Normal Monster', 'Fiend', 'DARK', 2, 700, 600, '对映在镜子上的东西施以催眠术，从而避开攻击的恶魔之镜。'),
(50287060, 'Archfiend of Gilfer', '暗黑魔族 基尔法恶魔', '暗黒魔族ギルファー・デーモン', 'Effect Monster', 'Fiend', 'DARK', 6, 2200, 2500, '①：这张卡被送去墓地时，以场上1只表侧表示怪兽为对象才能发动。墓地的这张卡当作攻击力下降500的装备卡使用给那只怪兽装备。'),
(63883999, 'Archfiend Palabyrinth', '伏恶魔殿－魔鬼的迷宫－', '伏魔殿－悪魔の迷宮－', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，自己场上的恶魔族怪兽的攻击力上升500。此外，选择自己场上1只名字带有「恶魔」的怪兽才能发动。选出选择的怪兽以外的自己场上1只恶魔族怪兽从游戏中除外，从自己的手卡·卡组·墓地选和选择的怪兽相同等级的1只名字带有「恶魔」的怪兽特殊召唤。「伏魔殿-恶魔的迷宫-」的这个效果1回合只能使用1次。'),
(87985506, 'Archfiend Playtime', '恶魔的谐谑', 'デーモンの諧謔', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只7星以下的「恶魔」怪兽特殊召唤。自己的额外卡组有表侧的「恶魔」仪式怪兽存在的场合，也能作为代替把「王家恶魔」「公爵恶魔」「殿下恶魔」各最多1只从手卡·卡组特殊召唤。'),
(49881766, 'Archfiend Soldier', '恶魔士兵', 'デーモン・ソルジャー', 'Normal Monster', 'Fiend', 'DARK', 4, 1900, 1500, '隶属于只招集恶魔中精兵的部队的战斗专家。被交付了任务就会确实地完成它而因此出名。'),
(90764871, 'Archfiend Strategy', '恶魔的棋盘游戏', 'デーモンの盤上遊戯', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：额外怪兽区域的恶魔族怪兽的攻击力上升1000。 ②：可以从以下效果选择1个发动。 ●从自己的手卡·墓地把1只恶魔族怪兽或1张「恶魔」卡除外才能发动。从卡组把场地魔法卡以外的1张「恶魔」卡加入手卡。 ●从卡组把1只「恶魔」灵摆怪兽表侧加入额外卡组。'),
(82997779, 'Archfiend Usurpation', NULL, NULL, 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, NULL),
(59969392, 'Archfiend Zombie-Skull', '不死骷髅恶魔', 'アンデット・スカル・デーモン', 'Synchro Monster', 'Zombie', 'DARK', 6, 2500, 1200, '「僵尸带菌者」＋调整以外的不死族怪兽2只以上 自己场上表侧表示存在的不死族怪兽不会被卡的效果破坏。'),
(53008933, 'Archfiend''s Advent', '恶魔的光来', 'デーモンの光来', 'Effect Monster', 'Fiend', 'DARK', 6, 2500, 1200, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上有「光之黄金柜」存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤的场合，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。这个效果的发动时自己场上没有「光之黄金柜」存在的场合，这个效果得到控制权的怪兽不能攻击。 ③：自己场上的其他怪兽的攻击力在自己回合内上升500。'),
(61248471, 'Archfiend''s Ascent', '恶魔超越', 'デーモンの超越', 'XYZ Monster', 'Fiend', 'DARK', 6, 2500, 1200, '6星怪兽×2 ①：这张卡只要在怪兽区域存在，卡名当作「恶魔召唤」使用。 ②：自己场上的「恶魔召唤」被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。 ③：超量召唤的这张卡被对方送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「恶魔召唤」特殊召唤。'),
(95825679, 'Archfiend''s Awakening', '恶魔降临', 'デーモンの降臨', 'Ritual Effect Monster', 'Fiend', 'DARK', 6, 2500, 1200, '「与奈落的契约」降临。 ①：这张卡只要在怪兽区域存在，卡名当作「恶魔召唤」使用。 ②：场上的这张卡不会被和仪式怪兽以外的怪兽的战斗破坏，不会被仪式怪兽以外的怪兽的效果破坏。 ③：仪式召唤的这张卡被对方送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「恶魔召唤」特殊召唤。'),
(64635042, 'Archfiend''s Call', '恶魔招来', 'デーモンの招来', 'Synchro Monster', 'Fiend', 'DARK', 6, 2500, 1200, '调整＋调整以外的怪兽1只以上 ①：这张卡只要在怪兽区域存在，卡名当作「恶魔召唤」使用。 ②：只要这张卡在怪兽区域存在，对方不能把自己场上的「恶魔召唤」作为效果的对象。 ③：同调召唤的这张卡被对方送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「恶魔召唤」特殊召唤。'),
(300302057, 'Archfiend''s Conscription', NULL, NULL, 'Skill Card', 'Titan', NULL, NULL, NULL, NULL, NULL),
(13379114, 'Archfiend''s Fervor', '恶魔的气魄', 'デーモンの気魄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：额外怪兽区域有自己的「恶魔」仪式怪兽存在的场合，以对方场上1张表侧表示卡为对象才能发动。那张卡的效果直到回合结束时无效。 ②：这张卡从手卡·场上除外的场合才能发动。从卡组把「恶魔的气魄」以外的1张「恶魔」卡加入手卡。'),
(5168381, 'Archfiend''s Ghastly Glitch', '恶魔之秘技', '悪魔の技', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有恶魔族怪兽存在的场合，以场上1张卡为对象才能发动。那张卡破坏。那之后，可以从卡组把1只恶魔族怪兽送去墓地。'),
(32775808, 'Archfiend''s Manifestation', '恶魔显现', 'デーモンの顕現', 'Fusion Monster', 'Fiend', 'DARK', 6, 2500, 1200, '「恶魔召唤」＋暗属性怪兽 ①：这张卡只要在怪兽区域存在，卡名当作「恶魔召唤」使用。 ②：只要这张卡在怪兽区域存在，自己场上的「恶魔召唤」的攻击力上升500。 ③：融合召唤的这张卡被对方送去墓地的场合才能发动。从自己的手卡·卡组·墓地选1只「恶魔召唤」特殊召唤。'),
(22796548, 'Archfiend''s Oath', '恶魔的宣告', 'デーモンの宣告', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：1回合1次，支付500基本分，宣言1个卡名才能发动。自己卡组最上面的卡翻开，宣言的卡的场合，那张卡加入手卡。不是的场合，翻开的卡送去墓地。'),
(300302058, 'Archfiend''s Promotion', NULL, NULL, 'Skill Card', 'Titan', NULL, NULL, NULL, NULL, NULL),
(56246017, 'Archfiend''s Roar', '恶魔的雄叫', 'デーモンの雄叫び', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '支付500基本分才能发动。从自己的墓地里特殊召唤1只名称中含有「恶魔」字样的怪兽上场。此怪兽不可作为任何情况下的祭品。本回合的结束阶段时，此怪兽被破坏。'),
(21438286, 'Archfiend''s Staff of Despair', '恶魔之杖', 'デーモンの杖', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽才能装备。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降装备怪兽的攻击力一半数值。 ②：给怪兽装备的这张卡被送去墓地的场合，支付1000基本分才能发动。这张卡回到手卡。'),
(59509952, 'Archlord Kristya', '大天使 克里斯蒂亚', '大天使クリスティア', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2300, '①：自己墓地的天使族怪兽只有4只的场合，这张卡可以从手卡特殊召唤。 ②：这张卡的①的方法特殊召唤成功的场合，以自己墓地1只天使族怪兽为对象发动。那只天使族怪兽加入手卡。 ③：只要这张卡在怪兽区域存在，双方不能把怪兽特殊召唤。 ④：场上的表侧表示的这张卡被送去墓地的场合，不去墓地回到持有者卡组最上面。'),
(18378582, 'Archlord Zerato', '大天使 杰拉特', '大天使ゼラート', 'Effect Monster', 'Fairy', 'LIGHT', 8, 2800, 2300, '这张卡不能进行通常召唤。这张卡仅当场上存在「天空的圣域」时，祭掉自己场上1只以表侧表示存在的「杰拉的战士」才能特殊召唤。从手卡将1张光属性怪兽卡弃到墓地，破坏对方场上存在的所有怪兽。此效果仅当自己场上存在「天空的圣域」时才适用。'),
(33212663, 'Archnemeses Eschatos', '大星义・终焉', 'アークネメシス・エスカトス', 'Effect Monster', 'Dragon', 'LIGHT', 11, 3000, 2500, '这张卡不能通常召唤。从自己墓地以及自己场上的表侧表示怪兽之中把3只种族不同的怪兽除外的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：场上的这张卡不会被效果破坏。 ②：宣言场上的怪兽1个种族才能发动。场上的宣言种族的怪兽全部破坏。直到下个回合的结束时，双方不能把宣言的种族的怪兽特殊召唤。'),
(6728559, 'Archnemeses Protos', '大星义・始源', 'アークネメシス・プロートス', 'Effect Monster', 'Wyrm', 'DARK', 11, 2500, 3000, '这张卡不能通常召唤。从自己的场上（表侧表示）·墓地把3只属性不同的怪兽除外的场合可以特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：场上的这张卡不会被效果破坏。 ②：宣言场上的怪兽1个属性才能发动。场上的宣言属性的怪兽全部破坏。直到下个回合的结束时，双方不能把宣言的属性的怪兽特殊召唤。'),
(38173725, 'Arcjet Lightcraft', '电弧火箭光船', 'アークジェット・ライトクラフター', 'Effect Monster', 'Machine', 'LIGHT', 9, NULL, 2100, '这个卡名的②的效果1回合只能使用1次。 ①：自己场上没有怪兽存在的场合，这张卡可以不用解放作召唤。 ②：这张卡召唤·特殊召唤成功的场合，以自己墓地1只8星以下的机械族怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的等级变成9星，效果无效化。 ③：只要这张卡在怪兽区域存在，自己不是机械族超量怪兽不能从额外卡组特殊召唤。'),
(40725446, 'Arequus the Shining Mars Saint', '荧焅圣 阿瑞库斯', '熒焅聖 アレクゥス', 'Effect Monster', 'Pyro', 'LIGHT', 5, 2000, 1800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②③的效果1回合各能使用1次。 ①：自己的魔法与陷阱区域有表侧表示卡存在的场合，这张卡可以从手卡特殊召唤。 ②：以自己场上1张表侧表示的魔法·陷阱卡为对象才能发动。那张卡和这张卡破坏。那之后，自己抽1张。 ③：这张卡被破坏的场合，以自己场上1只超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材。'),
(40706444, 'Argostars - Adventurous Arion', '阿尔戈☆群星－勇骏的阿里翁', 'ARG☆S－勇駿のアリオン', 'XYZ Monster', 'Warrior', 'DARK', 4, 2200, 2200, '4星怪兽×2 「阿尔戈☆群星-勇骏之阿里翁」1回合1次也能在自己场上的「阿尔戈☆群星」怪兽上面重叠来超量召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。从卡组把1张「阿尔戈☆群星」魔法卡加入手卡。 ②：自己·对方的准备阶段，把这张卡2个超量素材取除才能发动。从自己墓地把最多3张「阿尔戈☆群星」永续陷阱卡在自己的魔法与陷阱区域表侧表示放置。'),
(21050476, 'Argostars - Fierce Parthe', '阿尔戈☆群星－热斗之帕耳忒', 'ARG☆S－熱闘のパルテ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1400, 1400, '这个卡名的①③的效果1回合各能使用1次。 ①：自己·对方回合，把手卡的这张卡给对方观看才能发动。自己场上1张表侧表示的「阿尔戈☆群星」永续陷阱卡回到手卡，这张卡特殊召唤。 ②：这张卡的攻击力·守备力上升自己场上的其他的「阿尔戈☆群星」怪兽种类×700。 ③：把场上的这张卡除外才能发动。从手卡把1张永续陷阱卡盖放。这个效果盖放的卡在盖放的回合也能发动。'),
(30964246, 'Argostars - Giantslaying', '阿尔戈☆群星－巨人讨灭', 'ARG☆S－GiantKilling', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「阿尔戈☆群星」怪兽加入手卡。自己的怪兽区域有永续陷阱卡存在的场合或者持有把自身作为怪兽特殊召唤效果的永续陷阱卡在自己的魔法与陷阱区域存在的场合，可以再进行1只战士族怪兽的召唤。 ②：自己主要阶段把墓地的这张卡除外，以包含自己场上的「阿尔戈☆群星」永续陷阱卡的场上2张卡为对象才能发动。那些卡回到手卡。'),
(91438674, 'Argostars - Glorious Adra', '阿尔戈☆群星－荣冠的阿德拉', 'ARG☆S－栄冠のアドラ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 1800, '这个卡名的③的效果1回合只能使用1次。 ①：对方回合，自己场上有永续陷阱卡存在的场合，把这张卡从手卡除外才能发动。场上1只怪兽的攻击力直到回合结束时变成0。 ②：这张卡召唤的场合发动。这个回合，对方不能对应自己的永续陷阱卡的效果的发动把效果发动。 ③：把场上的这张卡除外才能发动。从手卡·卡组把最多2张「阿尔戈☆群星」永续陷阱卡在自己的魔法与陷阱区域表侧表示放置（同名卡最多1张）。'),
(2674965, 'Argostars - Home Stadium', '阿尔戈☆群星－主阵竞技场', 'ARG☆S－HomeStadium', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，支付1000基本分才能发动。自己的墓地·除外状态的1张「阿尔戈☆群星」卡加入手卡。 ②：每次从魔法与陷阱区域往自己场上有永续陷阱卡特殊召唤，给与对方500伤害。 ③：自己的「阿尔戈☆群星」怪兽除外中的状态，自己的永续陷阱卡在怪兽区域把效果发动的场合，以对方场上1张表侧表示卡为对象才能发动（同一连锁上最多1次）。那张卡的效果直到回合结束时无效。'),
(65889305, 'Argostars - Lightning Tydeu', '阿尔戈☆群星－紫电的堤丢尔', 'ARG☆S－紫電のテュデル', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的战士族怪兽的攻击力·守备力上升500。 ②：1回合1次，丢弃1张手卡才能发动。这张卡变成持有以下效果的效果怪兽（战士族·光·4星·攻/守2000）在怪兽区域特殊召唤（也当作陷阱卡使用）。那之后，可以从卡组把「阿尔戈☆群星-紫电的堤丢尔」以外的1张「阿尔戈☆群星」卡加入手卡。 ●自己·对方回合1次，可以发动。这张卡在自己的魔法与陷阱区域表侧表示放置。'),
(38379052, 'Argostars - Slayer Eteo', '阿尔戈☆群星－屠龙的厄忒欧', 'ARG☆S－屠龍のエテオ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己场上的战士族怪兽不会被效果破坏。 ②：1回合1次，对方把效果发动时才能发动。这张卡变成持有以下效果的效果怪兽（战士族·光·4星·攻/守800）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己的「阿尔戈☆群星」怪兽除外中的场合，可以再让场上1张卡回到手卡。 ●自己·对方回合1次，可以发动。这张卡在自己的魔法与陷阱区域表侧表示放置。'),
(91284003, 'Argostars - Swift Capane', '阿尔戈☆群星－飞燕的卡帕涅', 'ARG☆S－飛燕のカパネ', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，自己的战士族怪兽不会被战斗破坏。 ②：1回合1次，怪兽区域有永续陷阱卡存在的场合才能发动。这张卡变成持有以下效果的效果怪兽（战士族·光·4星·攻/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。自己的「阿尔戈☆群星」怪兽除外中的场合，再让自己回复500基本分。 ●自己·对方回合1次，可以发动。这张卡在自己的魔法与陷阱区域表侧表示放置。'),
(40502912, 'Aria the Melodious Diva', '幻奏音女 阿丽娅', '幻奏の音女アリア', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1200, '①：只要特殊召唤的这张卡在怪兽区域存在，自己场上的「幻奏」怪兽不会成为效果的对象，不会被战斗破坏。'),
(75730490, 'Ariane the Labrynth Servant', '拉比丽斯的仆从 亚莉安努', '白銀の城の召使い アリアーヌ', 'Effect Monster', 'Fiend', 'DARK', 4, 1800, 1100, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡以及自己场上盖放的卡之中把1张通常陷阱卡送去墓地才能发动。从卡组把「白银之城的召使 阿里亚娜」以外的1只4星以下的恶魔族怪兽守备表示特殊召唤。 ②：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。自己从卡组抽1张。那之后，以下效果可以适用。 ●从手卡把1只恶魔族怪兽特殊召唤或把1张魔法·陷阱卡盖放。'),
(1225009, 'Arianna the Labrynth Servant', '拉比丽斯的仆从 亚莉安娜', '白銀の城の召使い アリアンナ', 'Effect Monster', 'Fiend', 'DARK', 4, 1600, 2100, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把「白银之城的召使 阿里安娜」以外的1张「拉比林斯迷宫」卡加入手卡。 ②：自己的通常陷阱卡的效果让怪兽从场上离开的场合才能发动。自己从卡组抽1张。那之后，以下效果可以适用。 ●从手卡把1只恶魔族怪兽特殊召唤或把1张魔法·陷阱卡盖放。'),
(73602965, 'Arias the Labrynth Butler', '拉比丽斯的执事 亚莉安丝', '白銀の城の執事 アリアス', 'Effect Monster', 'Fiend', 'DARK', 6, 1500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段，把手卡·场上的这张卡送去墓地才能发动。从手卡把1只「拉比林斯迷宫」怪兽特殊召唤或把1张通常陷阱卡盖放。这个效果盖放的卡在盖放的回合也能发动。 ②：对方连锁「白银之城的执事 阿里亚斯」以外的自己的「拉比林斯迷宫」卡或通常陷阱卡的效果的发动把效果发动时才能把这个效果在墓地发动。这张卡特殊召唤。'),
(56827051, 'Ariel, Priestess of the Nekroz', '影灵衣的巫女 艾莉娅儿', '影霊衣の巫女 エリアル', 'Effect Monster', 'Psychic', 'WATER', 4, 1000, 1800, '这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，把手卡的「影灵衣」卡任意数量给对方观看才能发动。这张卡的等级直到回合结束时上升或下降给人观看的数量的数值。 ②：这张卡被效果解放的场合才能发动。从卡组把仪式怪兽以外的1只「影灵衣」怪兽加入手卡。'),
(65910922, 'Arionpos, Serpent of the Ghoti', '游魊之大蛇 阿里翁波斯', 'ゴーティスの大蛇アリオンポス', 'Synchro Monster', 'Fish', 'WATER', 6, 2100, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把1只6星以下的鱼族怪兽除外。 ②：这张卡作为同调素材送去墓地的场合，以自己墓地1只鱼族怪兽为对象才能发动。那只怪兽除外。那之后，可以把持有那只怪兽的等级以下的等级的1只鱼族怪兽从卡组加入手卡。'),
(29904964, 'Arisen Gaia the Fierce Knight', '觉醒暗黑骑士盖亚', '覚醒の暗黒騎士ガイア', 'Effect Monster', 'Warrior', 'DARK', 7, 2300, 2100, '「觉醒的暗黑骑士 盖亚」的②的效果1回合只能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以不用解放作召唤。 ②：这张卡被解放的场合才能发动。从自己的手卡·墓地选1只「混沌战士」怪兽特殊召唤。 ③：「混沌战士」怪兽的仪式召唤进行的场合，可以作为需要的等级数值的怪兽之内的1只，把墓地的这张卡除外。'),
(33282498, 'Arkbrave Dragon', '弧光勇烈龙', 'アークブレイブドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 7, 2400, 2000, '①：这张卡从墓地的特殊召唤成功的场合才能发动。对方场上的表侧表示的魔法·陷阱卡全部除外，这张卡的攻击力·守备力上升这个效果除外的卡数量×200。 ②：这张卡被送去墓地的下个回合的准备阶段，以「弧光勇烈龙」以外的自己墓地1只7·8星的龙族怪兽为对象才能发动。那只怪兽特殊召唤。'),
(50687050, 'Arktos XII - Chronochasm Vaylantz', '针渊之弈勇－阿尔克托斯ⅩⅡ', '針淵のヴァリアンツ－アルクトスⅩⅡ', 'Pendulum Effect Fusion Monster', 'Fairy', 'EARTH', 12, 3000, 3000, '5星以上的「群豪」怪兽×2 额外卡组的里侧表示的这张卡在把自己场上的上记卡解放的场合才能从额外卡组特殊召唤。这个卡名的①②的怪兽效果1回合各能使用1次。 ①：自己·对方回合可以发动。从主要怪兽区域选2只自己怪兽或者2只对方怪兽，那2只的位置交换。 ②：怪兽区域的卡向其他的怪兽区域移动的场合才能发动。选场上1张卡破坏。'),
(14708569, 'Arlownay', '阿罗妮', 'アルラウネ', 'Normal Monster', 'Plant', 'EARTH', 3, 800, 1000, '花中的女性散发着有毒的花粉。任何人都不能靠近她。'),
(36151751, 'Arma Knight', '菊石骑士', 'アンモ・ナイト', 'Normal Monster', 'Aqua', 'WATER', 4, 1000, 1200, '从很久以前就守护着大海的骑士。'),
(88033975, 'Armades, Keeper of Boundaries', '幻层守护者 阿玛迪斯', '幻層の守護者アルマデス', 'Synchro Monster', 'Fiend', 'LIGHT', 5, 2300, 1500, '调整＋调整以外的怪兽1只以上 这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·效果怪兽的效果不能发动。'),
(28493337, 'Armageddon Designator', '终焉之指名者', '終焉の指名者', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把1张手卡从游戏中除外才能发动。双方玩家在这次决斗中不能把为这张卡发动而除外的卡以及那些同名卡的效果发动。'),
(28985331, 'Armageddon Knight', '终末骑士', '終末の騎士', 'Effect Monster', 'Warrior', 'DARK', 4, 1400, 1200, '①：这张卡召唤·反转召唤·特殊召唤成功时才能发动。从卡组把1只暗属性怪兽送去墓地。'),
(53153481, 'Armaill', '甲铠', 'アーメイル', 'Normal Monster', 'Warrior', 'EARTH', 3, 700, 1300, '有着剑状尾的怪异战士。用双手和尾巴进行三连攻击。'),
(53770666, 'Armament Reincarnation', '武装转生', '武装転生', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：把最多有自己墓地的装备魔法卡以及持有把自身当作装备卡使用来装备效果的陷阱卡数量的「武装转生衍生物」（战士族·光·1星·攻/守500）在自己场上特殊召唤。那之后，以下可以适用。这个回合，自己不能把怪兽特殊召唤。 ●包含这张卡的自己的魔法与陷阱区域的卡全部破坏。那之后，装备魔法卡以及持有把自身当作装备卡使用来装备效果的陷阱卡从自己墓地尽可能到自己场上盖放。把陷阱卡盖放的场合，那些在盖放的回合也能发动。'),
(300302023, 'Armed and Ready!', NULL, NULL, 'Skill Card', 'Chazz Princet', NULL, NULL, NULL, NULL, NULL),
(90374791, 'Armed Changer', '武装转换', 'アームド・チェンジャー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '从自己手卡把1张装备魔法卡送去墓地发动。装备怪兽战斗破坏怪兽的场合，装备卡的控制者可以从自己墓地选择装备怪兽的攻击力以下的1只怪兽加入手卡。'),
(61606250, 'Armed Dragon Blitz', '武装龙之袭雷', '武装竜の襲雷', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不是龙族怪兽不能特殊召唤。 ①：以自己场上1只「武装龙」怪兽为对象才能发动。从自己的卡组·墓地选那1只同名怪兽加入手卡或无视召唤条件特殊召唤。这个效果特殊召唤的怪兽不能直接攻击。'),
(75906310, 'Armed Dragon Catapult Cannon', '武装龙强击炮', 'アームド・ドラゴン・カタパルトキャノン', 'Fusion Monster', 'Machine', 'LIGHT', 10, 3500, 3000, '「VWXYZ-神龙强击炮」＋「武装龙 LV7」 自己对上记的卡全部的特殊召唤成功的决斗中，把自己的场上·墓地的上记的卡除外的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：只要这张卡在怪兽区域存在，对方不能把和除外的自己·对方的卡同名卡的效果发动。 ②：对方回合1次，从卡组·额外卡组把1张卡除外才能发动。对方的场上·墓地的卡全部除外。'),
(34611551, 'Armed Dragon Flash', '武装龙之霹雳', '武装竜の霹靂', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1只3星「武装龙」怪兽守备表示特殊召唤。'),
(97091969, 'Armed Dragon Lightning', '武装龙之震霆', '武装竜の震霆', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：可以以自己场上1只「武装龙」怪兽为对象，从以下效果选择1个发动。 ●那只怪兽的攻击力上升那只怪兽的等级×100。 ●从自己墓地选持有那只怪兽的等级以下的等级的1只「武装龙」怪兽加入手卡。 ②：自己场上的「武装龙」怪兽被效果破坏的场合，可以作为代替把这张卡送去墓地。'),
(59464593, 'Armed Dragon LV10', '武装龙 LV10', 'アームド・ドラゴン LV１０', 'Effect Monster', 'Dragon', 'WIND', 10, 3000, 2000, '这张卡不能通常召唤。把自己场上1只「武装龙 LV7」解放的场合才能特殊召唤。 ①：把1张手卡送去墓地才能发动。对方场上的表侧表示怪兽全部破坏。'),
(84425220, 'Armed Dragon LV10 White', '武装龙 LV10－白', 'アームド・ドラゴン LV１０－ホワイト', 'Effect Monster', 'Dragon', 'LIGHT', 10, 3000, 2000, '这张卡不能通常召唤，用这张卡的效果才能特殊召唤。这个卡名的①的效果1回合只能使用1次。 ①：等级合计直到10为止从自己的场上·墓地把「武装龙」怪兽除外才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1张「白之衣」加入手卡。 ②：这张卡的控制者受到的效果伤害变成0。 ③：这张卡攻击的伤害步骤开始时才能发动。选场上1张卡破坏。'),
(980973, 'Armed Dragon LV3', '武装龙 LV3', 'アームド・ドラゴン LV３', 'Effect Monster', 'Dragon', 'WIND', 3, 1200, 900, '①：自己准备阶段，把场上的这张卡送去墓地才能发动。从手卡·卡组把1只「武装龙 LV5」特殊召唤。'),
(46384672, 'Armed Dragon LV5', '武装龙 LV5', 'アームド・ドラゴン LV５', 'Effect Monster', 'Dragon', 'WIND', 5, 2400, 1700, '①：从手卡把1只怪兽送去墓地，以对方场上1只表侧表示怪兽为对象才能发动。持有为这个效果发动而送去墓地的怪兽的攻击力以下的攻击力的作为对象的对方怪兽破坏。 ②：这张卡战斗破坏怪兽的回合的结束阶段，把场上的这张卡送去墓地才能发动。从手卡·卡组把1只「武装龙 LV7」特殊召唤。'),
(73879377, 'Armed Dragon LV7', '武装龙 LV7', 'アームド・ドラゴン LV７', 'Effect Monster', 'Dragon', 'WIND', 7, 2800, 1000, '这张卡不能通常召唤，用「武装龙 LV5」的效果才能特殊召唤。 ①：从手卡把1只怪兽送去墓地才能发动。持有送去墓地的怪兽的攻击力以下的攻击力的对方场上的怪兽全部破坏。'),
(58153103, 'Armed Dragon Thunder LV10', '武装龙闪电 LV10', 'アームド・ドラゴン・サンダー LV１０', 'Effect Monster', 'Dragon', 'WIND', 10, 3000, 2000, '①：「武装龙」怪兽的效果特殊召唤的这张卡得到自身的攻击力的以下效果。 ●1以上：卡名当作「武装龙 LV10」使用。 ●10以上：这个控制权不能变更。 ●100以上：不会被战斗破坏。 ●1000以上：对方回合1次，把1张手卡送去墓地，以场上1张其他卡为对象才能发动。那张卡破坏，自身的攻击力上升1000。 ●10000以上：1回合1次，可以发动。场上的其他卡全部破坏。'),
(57030525, 'Armed Dragon Thunder LV3', '武装龙闪电 LV3', 'アームド・ドラゴン・サンダー LV３', 'Effect Monster', 'Dragon', 'WIND', 3, 1200, 900, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「武装龙 LV3」使用。 ②：从手卡把1只怪兽送去墓地才能发动。场上的这张卡送去墓地，从手卡·卡组把1只5星以下的「武装龙」怪兽特殊召唤。 ③：这张卡为让龙族怪兽的效果发动而被送去墓地的场合才能发动。自己从卡组抽1张。'),
(21546416, 'Armed Dragon Thunder LV5', '武装龙闪电 LV5', 'アームド・ドラゴン・サンダー LV５', 'Effect Monster', 'Dragon', 'WIND', 5, 2400, 1700, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「武装龙 LV5」使用。 ②：从手卡把1只怪兽送去墓地才能发动。场上的这张卡送去墓地，从手卡·卡组把1只7星以下的「武装龙」怪兽特殊召唤。 ③：这张卡为让龙族怪兽的效果发动而被送去墓地的场合才能发动。从卡组把1只5星以上的龙族·风属性怪兽加入手卡。'),
(94141712, 'Armed Dragon Thunder LV7', '武装龙闪电 LV7', 'アームド・ドラゴン・サンダー LV７', 'Effect Monster', 'Dragon', 'WIND', 7, 2800, 1000, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「武装龙 LV7」使用。 ②：从手卡把1只怪兽送去墓地才能发动。场上的这张卡送去墓地，从手卡·卡组把1只10星以下的「武装龙」怪兽特殊召唤。 ③：这张卡为让龙族怪兽的效果发动而被送去墓地的场合才能发动。从卡组把1张「武装龙」卡加入手卡。'),
(57605303, 'Armed Dragon Thunderbolt', '武装龙之万雷', '武装竜の万雷', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以自己场上1只「武装龙」怪兽为对象才能发动。那只怪兽的攻击力上升持有那只怪兽的等级以下的等级的自己墓地的「武装龙」怪兽种类×1000。这个回合，那只怪兽给与对方的战斗伤害变成0。 ②：把墓地的这张卡除外，以自己墓地1张「武装龙」魔法卡为对象才能发动。那张卡加入手卡。'),
(75220074, 'Armed Dragon, the Armored Dragon', '铠龙-武装龙-', '鎧竜－アームド・ドラゴン－', 'Effect Monster', 'Dragon', 'WIND', 4, 1900, 1400, '①：这张卡战斗破坏对方怪兽时才能发动。从手卡·卡组把「铠龙-武装龙-」以外的1只5星以下的龙族·风属性怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能直接攻击。'),
(31817415, 'Armed Neos', '武装新宇侠', 'アームド・ネオス', 'Fusion Monster', 'Warrior', 'WIND', 10, 3500, 3000, '「元素英雄 新宇侠」＋「武装龙」怪兽 这张卡不用融合召唤不能特殊召唤。 ①：这张卡特殊召唤成功的场合才能发动。选自己墓地1只龙族怪兽，持有那个等级以下的等级的对方场上的怪兽全部破坏。 ②：这张卡战斗破坏怪兽时才能发动。这张卡得到以下效果。 ●双方的主要阶段，把这张卡解放才能发动。从额外卡组把1只「元素英雄」融合怪兽无视召唤条件特殊召唤。'),
(9076207, 'Armed Ninja', '青衣忍者', '青い忍者', 'Flip Effect Monster', 'Warrior', 'EARTH', 1, 300, 300, '①：这张卡反转的场合，以场上1张表侧表示的魔法卡或者场上盖放的1张魔法·陷阱卡为对象发动。那张魔法卡破坏（那张卡在场上盖放中的场合，翻开确认）。'),
(29330706, 'Armed Protector Dragon', '武装神龙 护甲龙', '武装神竜プロテクト・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 8, 2000, 2800, '①：这张卡的攻击力上升这张卡装备的装备卡数量×500。 ②：只要这张卡在怪兽区域存在，自己场上的表侧表示的装备卡不会被效果破坏。'),
(21056275, 'Armed Rebeellion', '武装蜂起', '武装蜂起', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡·卡组把1只攻击力1000以下的昆虫族怪兽特殊召唤。这个效果从卡组特殊召唤的场合，再把自己场上1只怪兽送去墓地。这张卡的发动后，直到回合结束时自己不是昆虫族怪兽不能特殊召唤。 ②：这张卡在墓地存在的状态，自己场上的表侧表示的昆虫族同调怪兽被战斗·效果破坏的场合，把这张卡除外才能发动。从卡组把1张「一齐蜂起」加入手卡。'),
(84430950, 'Armed Samurai - Ben Kei', '重装武者-弁庆', '重装武者－ベン・ケイ', 'Effect Monster', 'Warrior', 'DARK', 4, 500, 800, '每次的战斗阶段中，这张卡在通常攻击之上追加、这张卡装备的装备卡数量的攻击次数。'),
(20470500, 'Armed Sea Hunter', '武装海洋猎手', 'アームズ・シーハンター', 'Effect Monster', 'Sea Serpent', 'WATER', 4, 1800, 400, '自己场上有这张卡以外的水属性怪兽表侧表示存在的场合，和这张卡进行战斗的效果怪兽的效果在伤害计算后无效化。这张卡被破坏的场合，可以作为代替把自己场上表侧表示存在的1只3星以下的水属性怪兽破坏。'),
(36768783, 'Armillyre, the Starleader Dragon', '星导龙 阿米莱尔', '星導竜アーミライル', 'Link Monster', 'Dragon', 'DARK', NULL, 1400, NULL, '效果怪兽2只 这张卡不能作为连接素材。这个卡名的效果1回合只能使用1次。 ①：以这张卡所连接区1只表侧表示怪兽为对象才能发动。原本等级和那只怪兽相同的1只怪兽从手卡往作为这张卡所连接区的自己场上守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(43378048, 'Armityle the Chaos Phantasm', '混沌幻魔阿米泰尔', '混沌幻魔アーミタイル', 'Fusion Monster', 'Fiend', 'DARK', 12, NULL, NULL, '「神炎皇 乌利亚」＋「降雷皇 哈蒙」＋「幻魔皇 拉比艾尔」 把自己场上的上记卡除外的场合才能从额外卡组特殊召唤（不需要「融合」）。 ①：这张卡的攻击力在自己回合内上升10000。 ②：这张卡不会被战斗破坏。'),
(60110982, 'Armityle the Chaos Phantasm - Phantom of Fury', '混沌幻魔阿米泰尔－虚无幻影罗生闷', '混沌幻魔アーミタイル－虚無幻影羅生悶', 'Fusion Monster', 'Fiend', 'DARK', 12, NULL, NULL, '「神炎皇 乌利亚」＋「降雷皇 哈蒙」＋「幻魔皇 拉比艾尔」 ①：这张卡只要在怪兽区域存在，卡名当作「混沌幻魔 阿米泰尔」使用。 ②：1回合1次，自己主要阶段才能发动。这张卡的控制权移给对方。 ③：这张卡的控制权转移的回合的结束阶段发动。自己场上的卡全部除外。那之后，这张卡的原本持有者可以从自身的额外卡组把1只「混沌幻魔 阿米泰尔」无视召唤条件特殊召唤。'),
(79155167, 'Armor Blast', '虫甲爆破', 'アーマーブラスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1张名字带有「甲虫装机」的卡和对方场上表侧表示存在的2张卡发动。选择的卡破坏。'),
(79649195, 'Armor Break', '铠甲破坏', 'アーマーブレイク', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '使装备魔法卡的发动无效，并且将其破坏。'),
(87798440, 'Armor Breaker', '铠甲破坏士', 'アーマー・ブレイカー', 'Union Effect Monster', 'Warrior', 'EARTH', 3, 800, 800, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己场上的战士族怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽给与对方基本分战斗伤害时，场上存在的1张卡破坏。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(58827995, 'Armor Dragon Ritual', '铠龙降临', '鎧竜降臨', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「铠龙之圣骑士」的降临必需。这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到4以上的自己的手卡·场上的怪兽解放，从手卡把「铠龙之圣骑士」仪式召唤。 ②：从手卡以及自己场上的表侧表示怪兽之中把等级合计直到4以上的怪兽除外才能发动。墓地的这张卡除外，从自己墓地选1只「铠龙之圣骑士」特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(7180418, 'Armor Exe', '魔导铠甲 执行者', '魔導アーマー エグゼ', 'Effect Monster', 'Rock', 'LIGHT', 4, 2400, 1400, '这张卡召唤·反转召唤·特殊召唤的回合不能进行攻击。在自己与对方的每1个准备阶段，从自己场上除去1个魔力指示物，如果不除去魔力指示物，则这张卡被破坏。'),
(16272453, 'Armor Ninjitsu Art of Alchemy', '机甲忍法 黄金变换', '機甲忍法ゴールド・コンバージョン', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上有名字带有「忍法」的卡存在的场合才能发动。自己场上的名字带有「忍法」的卡全部破坏。那之后，从卡组抽2张卡。'),
(65150219, 'Armor Ninjitsu Art of Freezing', '机甲忍法 冻结封锁', '機甲忍法フリーズ・ロック', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「忍者」的怪兽存在的场合，对方怪兽的攻击宣言时才能把盖放的这张卡发动。那次攻击无效，战斗阶段结束。此外，只要自己场上有这张卡和名字带有「忍者」的怪兽存在，对方场上的全部怪兽不能把表示形式变更。'),
(2148918, 'Armor Ninjitsu Art of Rust Mist', '机甲忍法 锈蚀水雾', '機甲忍法ラスト・ミスト', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有名字带有「忍者」的怪兽存在，对方场上有怪兽特殊召唤时，那些特殊召唤的怪兽的攻击力变成一半。'),
(62742651, 'Armored Axon Kicker', '铠装念动力人', 'アーマード・サイキッカー', 'Effect Monster', 'Psychic', 'EARTH', 6, 2200, 1800, '自己场上有念动力族怪兽表侧表示存在的场合，这张卡可以不用解放作召唤。这张卡战斗破坏对方怪兽的场合，自己受到破坏怪兽的攻击力一半数值的伤害。并且可以再把持有受到的伤害数值以下的攻击力的1只怪兽从自己墓地特殊召唤。'),
(86915847, 'Armored Bee', '甲蜂', 'アーマード・ビー', 'Effect Monster', 'Insect', 'WIND', 4, 1600, 1200, '1回合1次，选择对方场上表侧表示存在的1只怪兽才能发动。选择的对方怪兽的攻击力直到结束阶段时变成一半数值。'),
(29374928, 'Armored Bitron', '装甲比特创机', 'アーマード・ビットロン', 'Effect Monster', 'Cyberse', 'DARK', 2, 500, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡解放才能发动。从卡组把「铠装比特机灵」以外的1只电子界族怪兽效果无效特殊召唤。这个回合，自己不是电子界族怪兽不能特殊召唤。 ②：这张卡在墓地存在，自己场上的连接3以上的连接怪兽被战斗或者对方的效果破坏的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(67159705, 'Armored Cybern', '装甲电子翼龙', 'アーマード・サイバーン', 'Union Effect Monster', 'Machine', 'WIND', 4, NULL, 2000, '①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只需以「电子龙」为素材的融合怪兽或者「电子龙」为对象，把这张卡当作装备卡使用给那只怪兽装备。装备怪兽被战斗·效果破坏的场合，作为代替把这张卡破坏。 ●装备的这张卡特殊召唤。 ②：1回合1次，以场上1只表侧表示怪兽为对象才能发动。装备怪兽的攻击力下降1000，作为对象的表侧表示怪兽破坏。'),
(36868108, 'Armored Glass', '玻璃铠', 'ガラスの鎧', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '装备卡给怪兽装备时才能发动。直到回合结束时场上的全部装备卡的效果无效。'),
(50789693, 'Armored Kappa', '铠甲河童', 'アーマー・カッパー', 'XYZ Monster', 'Psychic', 'WATER', 2, 400, 1000, '2星怪兽×2 「铠甲河童」的②的效果在决斗中只能使用1次。 ①：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力或者守备力上升1000。 ②：自己怪兽进行战斗的战斗步骤，丢弃1张手卡才能发动。这个回合，自己场上的怪兽不会被战斗破坏，自己受到的战斗伤害全部变成0。'),
(15480588, 'Armored Lizard', '铠蜥蜴', '鎧蜥蜴', 'Normal Monster', 'Reptile', 'EARTH', 4, 1500, 1200, '拥有坚硬躯体的蜥蜴。如果被咬到会立即毙命。'),
(16246527, 'Armored Rat', '铠鼠', '鎧ネズミ', 'Normal Monster', 'Beast', 'EARTH', 3, 950, 1100, '可以用像铠甲般坚固的毛守护身体的老鼠。'),
(27480536, 'Armored Shark', '装甲鲨', 'アーマード・シャーク', 'Effect Monster', 'Fish', 'WATER', 3, 500, 2000, '这个卡名在规则上也当作「铠装超量」卡使用。这个卡名的①②的效果1回合各能使用1次。 ①：从额外卡组把1只水属性超量怪兽送去墓地，以持有和那个阶级数值相同等级的自己墓地1只鱼族怪兽为对象才能发动。那只怪兽特殊召唤。 ②：对方回合，这张卡在墓地存在的场合，以自己场上1只水属性超量怪兽为对象才能发动。这张卡当作攻击力上升500的装备魔法卡使用给那只怪兽装备。'),
(17535588, 'Armored Starfish', '甲化海星', 'アーマード・スターフィッシュ', 'Normal Monster', 'Aqua', 'WATER', 4, 850, 1400, '表面坚固，守备力较高的青色海星。'),
(17170970, 'Armored White Bear', '铠装白熊', 'アーマード・ホワイトベア', 'Effect Monster', 'Beast', 'WATER', 4, 1800, 1400, '这个卡名的①②的效果1回合各能使用1次。 ①：场上有同调怪兽存在，这张卡召唤·特殊召唤成功的场合，以自己墓地1张场地魔法卡为对象才能发动。那张卡加入手卡。 ②：这张卡被战斗或者对方的效果破坏送去墓地的场合才能发动。从自己的卡组·墓地选「铠装白熊」以外的1只4星以下的兽族怪兽特殊召唤。'),
(73046708, 'Armored Xyz', '装甲超量', 'アーマード・エクシーズ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只表侧表示怪兽和自己墓地1只超量怪兽为对象才能发动。作为对象的墓地的怪兽当作持有以下效果的装备魔法卡使用给作为对象的场上的怪兽装备。 ●装备怪兽的攻击力变成和这张卡的攻击力相同。 ●装备怪兽的属性也当作和这张卡的属性相同属性使用。 ●装备怪兽攻击的伤害步骤结束时，把这张卡送去墓地才能发动。那只攻击怪兽只再1次可以继续攻击。'),
(20277860, 'Armored Zombie', '铠武者僵尸', '鎧武者ゾンビ', 'Normal Monster', 'Zombie', 'DARK', 3, 1500, NULL, '充满怨念而苏醒的武者，要警惕在黑暗中挥舞的太刀。'),
(73333463, 'Armoroid', '战甲机人 铠电合', 'アーマロイドガイデンゴー', 'Effect Monster', 'Machine', 'EARTH', 8, 2700, 2000, '①：把「机人」怪兽解放让这张卡上级召唤成功的场合发动。场上的魔法·陷阱卡全部除外。'),
(29071332, 'Armory Arm', '支援武器手', 'アームズ・エイド', 'Synchro Monster', 'Machine', 'LIGHT', 4, 1800, 1200, '调整＋调整以外的怪兽1只以上 1回合1次，自己的主要阶段时可以当作装备卡使用给怪兽装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用的场合，装备怪兽的攻击力上升1000。此外，装备怪兽战斗破坏怪兽送去墓地时，给与对方基本分破坏的怪兽的原本攻击力数值的伤害。'),
(38960450, 'Armory Call', '武器呼唤', 'アームズ・コール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组把1张装备魔法卡加入手卡。那之后，可以给可以把那张卡装备的自己场上1只怪兽装备。'),
(61775475, 'Arms of Genex Return Zero', 'A・O・G次代机 返零', 'A・O・G リターンゼロ', 'Synchro Monster', 'Machine', 'DARK', 10, 3100, 2950, '暗属性调整＋调整以外的怪兽1只以上 ①：对方把怪兽的效果发动时，把属性和那只怪兽相同的1只怪兽从自己墓地除外才能发动（这个回合，不能为这个卡名的这个效果发动而把相同属性的怪兽除外）。那个发动无效并破坏。 ②：1回合1次，以自己的墓地·除外状态的最多6只「次世代」怪兽为对象才能发动（相同属性最多1只）。那些怪兽回到卡组。那之后，可以把最多有那个数量的魔法与陷阱区域的卡破坏。'),
(32549749, 'Arms Regeneration', '武装再生', '武装再生', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：可以从以下效果选择1个发动。 ●以自己场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升800。 ●以自己或者对方的墓地1张装备魔法卡为对象才能发动。那张卡在自己场上盖放或给可以把那张卡装备的自己场上1只怪兽装备。'),
(22493812, 'Army Ant Token', '蚂蚁的增殖', 'アリの増殖', 'Token', 'Insect', NULL, NULL, NULL, NULL, NULL),
(29687169, 'Arnis, the Empowered Warrior', '魔装战士 阿尔尼斯', '魔装戦士 アルニス', 'Effect Monster', 'Warrior', 'FIRE', 4, 1700, 1200, '①：这张卡被对方怪兽的攻击破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的魔法师族怪兽攻击表示特殊召唤。'),
(25861589, 'Aroma Blend', '芬芳调香', 'アロマブレンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：丢弃1张手卡才能发动。从手卡·卡组把「湿润之风」「干渴之风」「恩惠之风」的其中1张在自己的魔法与陷阱区域表侧表示放置。 ②：把墓地的这张卡除外才能发动。自己的手卡·场上的怪兽作为融合素材除外，把1只植物族融合怪兽融合召唤。自己基本分比对方多的场合，也能把自己墓地的植物族怪兽除外作为融合素材。'),
(5050644, 'Aroma Garden', '芬芳花园', 'アロマガーデン', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：1回合1次，自己场上有「芳香」怪兽存在的场合才能发动。自己回复500基本分。这个效果的发动后，直到下次的对方回合结束时自己场上的怪兽的攻击力·守备力上升500。 ②：自己场上的「芳香」怪兽被战斗·效果破坏送去墓地的场合发动。自己回复1000基本分。'),
(29189613, 'Aroma Gardening', '芬芳园艺', 'アロマガーデニング', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己对「芳香」怪兽的召唤·特殊召唤成功的场合才能发动。自己回复1000基本分。 ②：自己基本分比对方少的场合，对方怪兽的攻击宣言时才能发动。从卡组把1只「芳香」怪兽特殊召唤。'),
(12804701, 'Aroma Healing', '芬芳疗愈', 'アロマヒーリング', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己回复自己场上的「芳香」怪兽种类×1000基本分。 ②：把墓地的这张卡除外，以自己墓地1只「芳香」怪兽为对象才能发动。那只怪兽特殊召唤。那之后，自己回复500基本分。这个效果特殊召唤的怪兽从场上离开的场合除外。'),
(21452275, 'Aroma Jar', '芬芳炉', 'アロマポット', 'Flip Effect Monster', 'Rock', 'WIND', 1, 500, 400, '①：只要反转过的这张卡在怪兽区域表侧表示存在，这张卡不会被战斗破坏。 ②：反转过的这张卡在怪兽区域表侧表示存在的场合，每次双方的结束阶段发动。自己回复500基本分。'),
(300202007, 'Aroma Strategy', NULL, NULL, 'Skill Card', 'Mai', NULL, NULL, NULL, NULL, NULL),
(85967160, 'Aromage Bergamot', '芬芳法师－蜂香薄荷', 'アロマージ－ベルガモット', 'Effect Monster', 'Plant', 'FIRE', 6, 2400, 1800, '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己的植物族怪兽向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合1次，自己基本分回复的场合发动。这张卡的攻击力·守备力直到对方回合的结束时上升1000。'),
(22174866, 'Aromage Cananga', '芬芳法师－依兰', 'アロマージ－カナンガ', 'Effect Monster', 'Plant', 'EARTH', 3, 1400, 1000, '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，对方场上的怪兽的攻击力·守备力下降500。 ②：1回合1次，自己基本分回复的场合，以对方场上1张魔法·陷阱卡为对象发动。那张卡回到持有者手卡。'),
(96789758, 'Aromage Jasmine', '芬芳法师－茉莉', 'アロマージ－ジャスミン', 'Effect Monster', 'Plant', 'LIGHT', 2, 100, 1900, '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把「芳香法师-茉莉」以外的1只植物族怪兽召唤。 ②：1回合1次，自己基本分回复的场合发动。自己从卡组抽1张。'),
(14169843, 'Aromage Laurel', '芬芳法师－月桂', 'アロマージ－ローリエ', 'Effect Monster', 'Plant', 'WIND', 1, 800, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：自己基本分比对方多的场合才能发动。这张卡从手卡特殊召唤。 ②：自己基本分回复的场合，以场上1只植物族怪兽为对象发动。这个回合，那只怪兽当作调整使用。 ③：这张卡被送去墓地的场合才能发动。自己回复500基本分。'),
(40663548, 'Aromage Marjoram', '芬芳法师－马郁兰', 'アロマージ－マジョラム', 'Effect Monster', 'Plant', 'DARK', 5, 2000, 1600, '这个卡名的①③的效果1回合各能使用1次。 ①：自己的植物族怪兽被战斗破坏时才能发动。这张卡从手卡特殊召唤。那之后，自己回复500基本分。 ②：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己的植物族怪兽的战斗发生的对自己的战斗伤害变成0。 ③：自己基本分回复的场合，以最多有自己场上的「芳香」怪兽数量的对方墓地的卡为对象发动。那些卡除外。'),
(58569561, 'Aromage Rosemary', '芬芳法师－迷迭香', 'アロマージ－ローズマリー', 'Effect Monster', 'Plant', 'WATER', 4, 1800, 700, '①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己的植物族怪兽攻击的场合，直到伤害步骤结束时对方不能把怪兽的效果发动。 ②：1回合1次，自己基本分回复的场合，以场上1只表侧表示怪兽为对象发动。那只怪兽的表示形式变更。'),
(73167098, 'Aromalilith Magnolia', '芬芳夜魔－木兰', 'アロマリリス－マグノリア', 'Fusion Monster', 'Plant', 'DARK', 8, 2600, 1800, '「芳香」怪兽＋植物族怪兽 ①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己场上的植物族怪兽不会被对方的效果破坏。 ②：1回合1次，支付2000基本分才能发动。把自己场上的「湿润之风」「干渴之风」「恩惠之风」数量的场上的卡除外。 ③：1回合1次，自己基本分回复的场合才能发动（伤害步骤也能发动）。自己场上的全部植物族怪兽的攻击力直到回合结束时上升那个数值。'),
(24689197, 'Aromalilith Rosalina', '芬芳夜魔－白千层', 'アロマリリス－ロザリーナ', 'Tuner Monster', 'Plant', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己场上1只「芳香」怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力一半的数值。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只调整以外的「芳香」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是植物族怪兽不能特殊召唤。'),
(30989084, 'Aromalilith Rosemary', '芬芳夜魔－迷迭香', 'アロマリリス－ローズマリー', 'Link Monster', 'Plant', 'DARK', NULL, 2200, NULL, '植物族怪兽2只以上 这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「芳香」卡加入手卡。 ②：自己基本分回复的场合才能发动（伤害步骤也能发动）。从手卡把最多3只「芳香」怪兽在作为这张卡所连接区的自己场上特殊召唤。 ③：把这张卡所连接区1只怪兽解放，以场上1张卡为对象才能发动。那张卡除外，自己回复1000基本分。'),
(16759958, 'Aromaseraphy Angelica', '芬芳炽天使－欧白芷', 'アロマセラフィ－アンゼリカ', 'Tuner Monster', 'Plant', 'LIGHT', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡从手卡丢弃，以自己墓地1只「芳香」怪兽为对象才能发动。自己基本分回复那只怪兽的攻击力的数值。 ②：这张卡在墓地存在，自己基本分比对方多，自己场上有「芳香」怪兽存在的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(21200905, 'Aromaseraphy Jasmine', '芬芳炽天使－茉莉', 'アロマセラフィ－ジャスミン', 'Link Monster', 'Plant', 'LIGHT', NULL, 1800, NULL, '植物族怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：自己基本分比对方多的场合，这张卡以及这张卡所连接区的植物族怪兽不会被战斗破坏。 ②：把这张卡所连接区1只自己怪兽解放才能发动。从卡组把1只植物族怪兽守备表示特殊召唤。 ③：1回合1次，自己基本分回复的场合发动。从卡组把1只植物族怪兽加入手卡。'),
(38148100, 'Aromaseraphy Rosemary', '芬芳炽天使－迷迭香', 'アロマセラフィ－ローズマリー', 'Synchro Monster', 'Plant', 'LIGHT', 5, 2000, 900, '调整＋调整以外的怪兽1只以上 ①：只要自己基本分比对方多并有这张卡在怪兽区域存在，自己场上的植物族怪兽的攻击力·守备力上升500。 ②：1回合1次，自己基本分回复的场合，以对方场上1张表侧表示卡为对象发动。那张卡的效果直到回合结束时无效。'),
(79656239, 'Aromaseraphy Sweet Marjoram', '芬芳炽天使－香甜马郁兰', 'アロマセラフィ－スイート・マジョラム', 'Synchro Monster', 'Plant', 'LIGHT', 6, 2200, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡同调召唤的场合才能发动。从卡组把「湿润之风」「干渴之风」「恩惠之风」的其中1张加入手卡。 ②：只要自己基本分比对方多并有这张卡在怪兽区域存在，对方不能把自己场上的植物族怪兽作为效果的对象。 ③：自己基本分回复的场合，以对方场上1张卡为对象发动。那张卡破坏。'),
(34172284, 'Aron, the Ogdoadic King', '溟界王－阿泷', '溟界王－アロン', 'Effect Monster', 'Reptile', 'LIGHT', 8, 2500, 2800, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，把自己场上2只怪兽解放才能发动。这张卡特殊召唤。 ②：对方在抽卡阶段以外把卡加入手卡的场合才能发动。对方手卡随机选1张送去墓地。 ③：对方场上的怪兽被效果送去墓地的场合才能发动。从自己的卡组·墓地选「溟界王-阿隆」以外的1只光·暗属性的爬虫类族怪兽加入手卡。'),
(69296555, 'Array of Revealing Light', '光之护封阵', '光の護封陣', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '宣言1个种族。宣言的种族的全部怪兽召唤·反转召唤·特殊召唤的回合不能进行攻击宣言。'),
(29508346, 'Arrivalrivals', '对手碰对头', 'ライバル・アライバル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己·对方的战斗阶段才能发动。把1只怪兽召唤。'),
(365213, 'Arrive in Light', '随光而来的奇迹', '光来する奇跡', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：作为这张卡的发动时的效果处理，从手卡·卡组选1只龙族·1星怪兽在卡组最上面放置。 ②：双方不能让场上的「星尘龙」以及有那个卡名记述的同调怪兽回到额外卡组。 ③：同调怪兽特殊召唤的场合才能发动。从以下效果选1个适用。这个回合，自己的「光来的奇迹」的效果不能有相同效果适用。 ●自己从卡组抽1张。 ●从手卡把1只调整特殊召唤。'),
(49652661, 'Arsenal Audit', '武器库整理', '武器庫整理', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把最多2张装备魔法卡送去墓地（同名卡最多1张）。 ②：把墓地的这张卡除外，以自己场上1只表侧表示怪兽为对象才能发动。把最多2张那只怪兽可以装备的装备魔法卡从自己的手卡·墓地给那只怪兽装备（同名卡最多1张）。只要这个效果把装备魔法卡装备中，那只怪兽给与对方的战斗伤害变成一半。'),
(42364374, 'Arsenal Bug', '甲蝇', 'アーマード・フライ', 'Effect Monster', 'Insect', 'EARTH', 3, 2000, 2000, '自己的场上没有这张卡以外的昆虫族存在，这张卡的攻击力守备力变成1000。'),
(55348096, 'Arsenal Robber', '武器库盗贼', '武器庫荒らし', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方从卡组里选择1张装备魔法卡送去墓地。'),
(85489096, 'Arsenal Summoner', '武器召唤师', 'ウェポンサモナー', 'Flip Effect Monster', 'Spellcaster', 'WIND', 4, 1600, 1600, '①：这张卡反转的场合发动。从卡组把1张「守护者」卡加入手卡。'),
(34755994, 'Artemis, the Magistus Moon Maiden', '伟魔少女 圣魔之阿耳忒弥斯', '聖魔の乙女アルテミス', 'Link Monster', 'Spellcaster', 'LIGHT', NULL, 800, NULL, '4星以下的魔法师族怪兽1只 自己对「圣魔之少女 阿耳特弥斯」1回合只能有1次特殊召唤，那些①②的效果1回合各能使用1次。 ①：这张卡在怪兽区域存在的状态，「大贤者」怪兽召唤·特殊召唤的场合，以那之内的1只为对象才能发动。自己场上的这张卡当作装备魔法卡使用给那只怪兽装备。 ②：这张卡装备中的场合才能发动。从卡组把1只「大贤者」怪兽加入手卡。'),
(11475049, 'Artifact Achilleshield', '古遗物－阿基里斯', 'アーティファクト－アキレウス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1500, 2200, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。对方回合中这张卡特殊召唤成功的场合，这个回合对方不能把自己场上的名字带有「古遗物」的怪兽作为攻击对象。'),
(85080444, 'Artifact Aegis', '古遗物－埃癸斯', 'アーティファクト－アイギス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1200, 2500, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。对方回合中这张卡特殊召唤成功的场合，直到回合结束时，自己场上的名字带有「古遗物」的怪兽不会成为对方的卡的效果的对象，不会被对方的卡的效果破坏。'),
(12697630, 'Artifact Beagalltach', '古遗物－贝加尔挞', 'アーティファクト－ベガルタ', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1400, 2100, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。对方回合中这张卡特殊召唤成功的场合，选自己场上盖放的最多2张卡破坏。「古遗物-微怒剑」的这个效果1回合只能使用1次。'),
(84268896, 'Artifact Caduceus', '古遗物－卡多克乌斯', 'アーティファクト－カドケウス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1600, 2400, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。此外，只要这张卡在自己场上表侧表示存在，对方回合中名字带有「古遗物」的怪兽特殊召唤时，从卡组抽1张卡。「古遗物-商神杖」在自己场上只能有1只表侧表示存在。'),
(8873112, 'Artifact Chakram', '古遗物－查克拉姆', 'アーティファクト－チャクラム', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1900, 2000, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：要让自己场上的魔法·陷阱卡破坏的效果发动时，让自己场上盖放的1张魔法·陷阱卡回到持有者手卡才能发动。这张卡从手卡特殊召唤。'),
(7480763, 'Artifact Dagda', '古遗物－达格达', 'アーティファクト－ダグザ', 'Link Monster', 'Fairy', 'LIGHT', NULL, 1500, NULL, '卡名不同的怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡以外的场上的卡的效果发动时才能发动。从手卡·卡组选1只「古遗物」怪兽当作魔法卡使用在自己的魔法与陷阱区域盖放。这个效果盖放的卡在下次的对方结束阶段破坏。 ②：连接召唤的这张卡在对方回合被破坏的场合才能发动。从自己墓地选1只「古遗物」怪兽守备表示特殊召唤。'),
(69840739, 'Artifact Durendal', '古遗物－杜兰德尔', 'アーティファクト－デュランダル', 'XYZ Monster', 'Fairy', 'LIGHT', 5, 2400, 2100, '5星怪兽×2 ①：1回合1次，可以从以下效果选择1个发动。这个效果在对方回合也能发动。 ●在场上的怪兽的效果发动时或者在通常魔法·通常陷阱卡发动时，把这张卡1个超量素材取除才能发动。那个效果变成「选对方场上1张魔法·陷阱卡破坏」。 ●把这张卡1个超量素材取除才能发动。双方让手卡全部回到卡组洗切。那之后，双方各自从卡组抽出自身回到卡组的数量。'),
(48086335, 'Artifact Failnaught', '古遗物－菲尔诺特', 'アーティファクト－フェイルノート', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2000, 1600, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。对方回合中这张卡特殊召唤成功的场合，可以从自己墓地选择1只名字带有「古遗物」的怪兽在自己的魔法与陷阱卡区域盖放。'),
(29223325, 'Artifact Ignition', '古遗物动力机芯', 'アーティファクト・ムーブメント', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏，从卡组选1只「古遗物」怪兽当作魔法卡使用在自己的魔法与陷阱区域盖放。 ②：这张卡被对方破坏的场合发动。下次的对方战斗阶段跳过。'),
(47863787, 'Artifact Labrys', '古遗物－拉布留斯', 'アーティファクト－ラブリュス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2300, 1000, '这张卡可以当作魔法卡使用从手卡到魔法与陷阱卡区域盖放。魔法与陷阱卡区域盖放的这张卡在对方回合被破坏送去墓地时，这张卡特殊召唤。此外，名字带有「古遗物」的卡被破坏送去自己墓地时才能发动。这张卡从手卡特殊召唤。'),
(34267821, 'Artifact Lancea', '古遗物－朗基努斯', 'アーティファクト－ロンギヌス', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1700, 2300, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：对方回合，把手卡·场上的这张卡解放才能发动。这个回合，双方不能把卡除外。'),
(80237445, 'Artifact Mjollnir', '古遗物－妙尔尼尔', 'アーティファクト－ミョルニル', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1300, 1800, '这个卡名的③的效果1回合只能使用1次。 ①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：对方回合，这张卡特殊召唤成功的场合，以自己墓地1只「古遗物」怪兽为对象发动。那只怪兽守备表示特殊召唤。这个效果的发动后，直到下个回合的结束时自己不是「古遗物」怪兽不能特殊召唤。'),
(85103922, 'Artifact Moralltach', '古遗物－魔拉尔挞', 'アーティファクト－モラルタ', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2100, 1400, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：对方回合，这张卡特殊召唤成功的场合才能发动。选对方场上1张表侧表示的卡破坏。'),
(12444060, 'Artifact Sanctum', '古遗物之神智', 'アーティファクトの神智', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能进行战斗阶段。 ①：从卡组把1只「古遗物」怪兽特殊召唤。 ②：这张卡被对方破坏的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(20292186, 'Artifact Scythe', '古遗物－戴思塞斯', 'アーティファクト－デスサイズ', 'Effect Monster', 'Fairy', 'LIGHT', 5, 2200, 900, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：对方回合，这张卡特殊召唤成功的场合发动。这个回合，对方不能从额外卡组把怪兽特殊召唤。'),
(69304426, 'Artifact Vajra', '古遗物－伐折罗', 'アーティファクト－ヴァジュラ', 'Effect Monster', 'Fairy', 'LIGHT', 5, 1800, 1900, '①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：魔法与陷阱区域盖放的这张卡在对方回合被破坏送去墓地的场合发动。这张卡特殊召唤。 ③：对方回合，这张卡特殊召唤成功的场合发动。自己的魔法与陷阱区域的卡全部破坏。 ④：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。'),
(56611470, 'Artifacts Unleashed', '古遗物之解放', 'アーティファクトの解放', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '选择自己场上2只名字带有「古遗物」的怪兽才能发动。只用选择的2只怪兽为素材把1只超量怪兽超量召唤。这张卡发动过的回合，名字带有「古遗物」的怪兽以外的自己场上的怪兽不能攻击。此外，这张卡被对方破坏的场合，把手卡1只光属性·5星怪兽给对方观看才能发动。从卡组抽1张卡。'),
(7913375, 'Artillery Catapult Turtle', '炮击的弹射龟', '砲撃のカタパルト・タートル', 'Effect Monster', 'Aqua', 'WATER', 4, 1000, 2000, '这个卡名的效果1回合只能使用1次。 ①：把自己场上1只怪兽解放才能发动。从手卡·卡组把1只「暗黑骑士 盖亚」怪兽或者龙族·5星怪兽特殊召唤。'),
(74733322, 'Artmage Academic Arcane Arts Acropolis', '神艺学都', '神芸学都アルトメギア', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己在通常召唤外加上只有1次，自己主要阶段可以把1只「无垢者 米底乌斯」召唤。 ②：从手卡丢弃1张魔法·陷阱卡，宣言1个同名怪兽不在自己场上存在的「神艺」怪兽的卡名才能发动（这个回合，不能为这个卡名的这个效果发动而宣言相同卡名）。宣言的1只怪兽从卡组加入手卡。这个回合，自己不是「神艺」怪兽以及「无垢者 米底乌斯」不能特殊召唤（除从额外卡组的特殊召唤外）。'),
(27184601, 'Artmage Diactorus', '神艺狱徒 迪亚克特罗斯', '神芸獄徒 ディアクトロス', 'Fusion Monster', 'Fairy', 'LIGHT', 8, 2800, 2500, '「无垢者 米底乌斯」＋「神艺」怪兽 这个卡名的①②③的效果1回合各能使用1次。 ①：以场上1只怪兽为对象才能发动。那只怪兽的表示形式变更。 ②：自己场上的怪兽的种族是3种类以上，对方把魔法·陷阱·怪兽的效果在场上发动时才能发动。那个发动无效并破坏。 ③：融合召唤的这张卡被破坏的场合才能发动。自己的手卡·卡组·除外状态的1只「无垢者 米底乌斯」特殊召唤。'),
(34541940, 'Artmage Finmel', '神艺学徒 珐艺美忒', '神芸学徒 ファインメルト', 'Effect Monster', 'Warrior', 'LIGHT', 7, 2400, 1500, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「神艺」卡存在的场合才能发动。这张卡从手卡特殊召唤。那之后，自己可以抽1张。 ②：对方不能把自己场上的6星以下的「神艺」怪兽作为效果的对象。 ③：自己·对方的主要阶段，自己场上的怪兽的种族是3种类以上的场合才能发动。对方场上的全部表侧表示怪兽的效果无效化，那些攻击力直到回合结束时变成一半。'),
(60946049, 'Artmage Graflare', '神艺学徒 格拉弗雷鸦', '神芸学徒 グラフレア', 'Effect Monster', 'Dragon', 'LIGHT', 5, 2100, 1500, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「神艺」卡存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从卡组把1张「神艺」魔法卡在自己场上盖放。 ②：这张卡1回合只有1次不会被战斗破坏。 ③：以对方场上1张魔法·陷阱卡为对象才能发动（自己场上的怪兽的种族是3种类以上的场合，这个效果在对方回合也能发动）。那张卡破坏。'),
(44654994, 'Artmage Impasto -Recapture-', NULL, NULL, 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, NULL),
(97434754, 'Artmage Litera', '神艺学徒 璃天乐', '神芸学徒 リテラ', 'Effect Monster', 'Spellcaster', 'LIGHT', 3, 400, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「神艺」卡存在的场合才能发动。这张卡从手卡特殊召唤。那之后，可以从自己墓地把1张「神艺」卡加入手卡。 ②：这张卡的战斗发生的对自己的战斗伤害变成0。 ③：对方主要阶段才能发动。从自己的手卡·墓地把「神艺学徒 莉泰拉」以外的1只「神艺」怪兽特殊召唤。那之后，场上的这张卡回到手卡。'),
(37517035, 'Artmage Masterwork -Succession-', '神艺杰作－继承－', 'アルトメギア・マスターワーク－継承－', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。包含「神艺」怪兽的自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。场地区域有卡存在的场合，再让这个效果特殊召唤的怪兽的攻击力上升500。 ②：自己主要阶段把墓地的这张卡除外，以自己墓地3张「神艺」卡为对象才能发动（同名卡最多1张）。那些卡回到卡组。'),
(21720439, 'Artmage Movement -Pedigree-', '神艺时势－血统－', 'アルトメギア・ムーヴメント－血統－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合才能发动。同名卡不在自己场上存在的1只「神艺」怪兽从卡组守备表示特殊召唤。 ②：这张卡为让「神艺学都 神艺学园」的效果发动而被送去墓地的场合才能发动。自己的墓地·除外状态的1张「神艺」陷阱卡加入手卡。'),
(74631897, 'Artmage Non-Finito', '未竟神艺 智慧之少女', '神芸なる知恵の乙女', 'Fusion Monster', 'Illusion', 'EARTH', 7, 2400, 1500, '「神艺」怪兽×2 「神艺智慧少女」1回合1次用融合召唤以及以下方法才能特殊召唤。 ●把手卡1张魔法·陷阱卡丢弃，把自己的手卡·场上1只7星以上的「神艺」怪兽解放的场合可以从额外卡组特殊召唤。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张「神艺」魔法·陷阱卡在自己场上盖放。 ②：对方回合才能发动1次。自己场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(23599634, 'Artmage Pact -Awakening-', '神艺援助－觉醒－', 'アルトメギア・メセナ－覚醒－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「神艺」怪兽或「无垢者 米底乌斯」特殊召唤。这个回合，包含把融合怪兽融合召唤效果的效果由自己发动的场合，那个发动不会被无效化，在那次融合召唤成功时对方不能把卡的效果发动。 ②：把墓地的这张卡除外，以自己场上1只「神艺」怪兽为对象才能发动。那只怪兽回到手卡·额外卡组，对方场上1张卡破坏。'),
(17719582, 'Artmage Peripeteia -Turmoil-', '神艺逆转－动荡－', 'アルトメギア・ペリペティア－激動－', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次，这些效果发动的回合，自己不是融合怪兽不能从额外卡组特殊召唤。 ①：以对方墓地1只怪兽为对象才能发动。自己场上1只「神艺」怪兽回到手卡·额外卡组，作为对象的怪兽效果无效在自己场上特殊召唤。 ②：这张卡为让「神艺学都 神艺学园」的效果发动而被送去墓地的场合才能发动。自己的墓地·除外状态的1张「神艺」魔法卡加入手卡。'),
(23829452, 'Artmage Power Patron', '神艺之狱神兽', 'アルトメギアの獄神獣', 'Effect Monster', 'Illusion', 'EARTH', 1, 300, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：自己不是融合怪兽不能从额外卡组特殊召唤。 ②：自己·对方的主要阶段才能发动。包含场上的这张卡的自己的手卡·场上的怪兽作为融合素材，把1只「神艺」融合怪兽或「创狱神 涅瓦」融合召唤。 ③：这张卡从手卡·场上送去墓地的场合才能发动。同名卡不在自己墓地存在的1张「神艺」魔法·陷阱卡从卡组加入手卡。'),
(1122030, 'Artmage Vandalism -Assault-', '神艺亵渎－袭击－', 'アルトメギア・ヴァンダリズム－襲撃－', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「无垢者 米底乌斯」加入手卡。 ②：以自己场上1只表侧表示怪兽为对象才能发动。这个回合，把那只表侧表示怪兽作为融合素材的场合，可以当作「神艺」怪兽使用。 ③：自己场上的「神艺学都 神艺学园」被效果破坏的场合，可以作为代替把场上的这张卡送去墓地。'),
(74011784, 'Artmage Varnish -Alteration-', '神艺护漆－改变－', 'アルトメギア・バーニッシュ－改変－', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的卡组·墓地把1张「神艺学都 神艺学园」在自己的场地区域表侧表示放置。自己场上有「神艺学都 神艺学园」存在的场合，作为代替从卡组把「神艺学的消失-改变-」以外的1张「神艺」卡加入手卡。 ②：自己的「神艺」怪兽被选择作为攻击对象时，把墓地的这张卡除外才能发动。那次攻击无效。那之后，可以从手卡把1只「无垢者 米底乌斯」特殊召唤。'),
(21223277, 'Artorigus, King of the Noble Knights', '圣骑士王 阿托利斯', '聖騎士王アルトリウス', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2000, 2000, '4星「圣骑士」怪兽×2 ①：这张卡超量召唤成功时，以自己墓地最多3张「圣剑」装备魔法卡为对象才能发动（同名卡最多1张）。那些卡给这张卡装备。 ②：1回合1次，把这张卡1个超量素材取除才能发动。选最多有自己场上的「圣剑」装备魔法卡数量的场上的魔法·陷阱卡破坏。'),
(71821687, 'Ascator, Dawnwalker', '使神官－阿斯卡托尔', '使神官－アスカトル', 'Effect Monster', 'Spellcaster', 'EARTH', 5, 2300, 1500, '这个卡名的效果1回合只能使用1次，这个效果发动的回合，自己不是同调怪兽不能从额外卡组特殊召唤。 ①：把这张卡以外的1张手卡丢弃才能发动。这张卡从手卡守备表示特殊召唤。那之后，可以从手卡·卡组把1只「赤蚁」特殊召唤。'),
(88301833, 'Ascending Soul', '升华之魂', '昇華する魂', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '仪式怪兽仪式召唤成功时，可以选择那次仪式召唤解放的自己墓地存在的1只怪兽加入手卡。这个效果1回合只能使用1次。'),
(37910722, 'Ascension Sky Dragon', '天穹霸龙 龙腾', '天穹覇龍ドラゴアセンション', 'Synchro Monster', 'Dragon', 'LIGHT', 10, -1, 3000, '调整＋调整以外的怪兽1只以上 这张卡同调召唤成功时，这张卡的攻击力上升自己手卡数量×800的数值。场上的这张卡被对方破坏送去墓地时，若这张卡的同调召唤使用过的一组同调素材怪兽在自己墓地齐集，可以把那一组特殊召唤。这个效果特殊召唤的怪兽的效果无效化。「天穹霸龙 龙腾」的这个效果1回合只能使用1次。'),
(27821104, 'Asceticism of the Six Samurai', '六武众之荒行', '六武衆の荒行', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：以自己场上1只「六武众」怪兽为对象才能发动。和那只怪兽是卡名不同并是攻击力相同的1只「六武众」怪兽从卡组特殊召唤。作为对象的怪兽在这个回合的结束阶段破坏。'),
(14558127, 'Ash Blossom & Joyous Spring', '灰流丽', '灰流うらら', 'Tuner Monster', 'Zombie', 'FIRE', 3, NULL, 1800, '这个卡名的效果1回合只能使用1次。 ①：包含以下其中任意种效果的魔法·陷阱·怪兽的效果发动时，把这张卡从手卡丢弃才能发动。那个效果无效。 ●从卡组把卡加入手卡的效果 ●从卡组把怪兽特殊召唤的效果 ●从卡组把卡送去墓地的效果'),
(66848311, 'Ashened for Eternity', '无尽的灰灭', '終わりなき灰滅', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的②的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从自己墓地把1只「灰灭」怪兽或「灭亡龙 威多释」加入手卡。 ②：以原本持有者是自己的对方场上1只表侧表示怪兽为对象才能发动。得到那只怪兽的控制权。那之后，可以让对方场上的全部表侧表示怪兽的攻击力直到回合结束时下降作为对象的怪兽的原本攻击力数值。'),
(34813443, 'Ashened to Endlessness', '无境的灰灭', '果てなき灰滅', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。包含「灭亡龙 威多释」的自己·对方场上的怪兽作为融合素材，把1只炎族融合怪兽融合召唤。这个效果特殊召唤的怪兽的攻击力上升那些作为融合素材的怪兽数量×500。 ②：从自己墓地把1只炎族·暗属性怪兽和这张卡除外才能发动。对方场上的全部怪兽直到回合结束时变成炎族。'),
(44376395, 'ASHLAN U1000', '阿修LAN U1000', NULL, 'Link Monster', 'Cyberse', 'LIGHT', NULL, 1400, NULL, '种族·属性不同的怪兽2只 这张卡所连接区的仪式怪兽向守备表示怪兽攻击的场合，给与对方攻击力超过那个守备力数值的战斗伤害。 「阿修LAN U1000」的以下效果1回合各能使用1次。 可以把手卡1只仪式怪兽给对方出示；从卡组把和出示怪兽种族·属性不同的1只仪式怪兽加入手卡。 自己仪式召唤的场合（伤害步骤除外）：可以以对方场上1张表侧表示卡为对象；那张卡回到手卡。'),
(58996839, 'Ashoka Pillar', '阿育王石柱', 'アショカ・ピラー', 'Effect Monster', 'Rock', 'EARTH', 3, NULL, 2200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·反转召唤·特殊召唤的场合才能发动。从卡组把1张装备魔法卡加入手卡。这张卡是攻击表示的场合，再让这张卡变成守备表示。 ②：这张卡被战斗·效果破坏的场合发动。自己受到2000伤害。'),
(80993256, 'Ashura King', '亚种罗王', '亜種羅王', 'XYZ Monster', 'Warrior', 'EARTH', 3, 2100, NULL, '3星怪兽×3只以上 这个卡名的③的效果1回合只能使用1次。 ①：持有超量素材的这张卡在同1次的战斗阶段中可以作出最多有那个数量的攻击。 ②：这张卡进行战斗的伤害步骤开始时发动。这张卡的攻击力上升200。 ③：这张卡以外的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(46815301, 'Askaan, the Bicorned Ghoti', '游魊之双角 阿斯坎', 'ゴーティスの双角アスカーン', 'Synchro Monster', 'Fish', 'WATER', 8, 2700, NULL, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡同调召唤的场合，以自己场上1只鱼族怪兽和对方场上1张卡为对象才能发动。那些卡除外。 ②：这张卡被除外的场合，从自己墓地把1只鱼族怪兽除外才能发动。这张卡特殊召唤。'),
(99657399, 'Asleep at the Switch', '油断大敌', '油断大敵', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方基本分回复时才能发动。选择对方场上存在的1只怪兽破坏。'),
(85771020, 'Asmo Token', '堕天使 阿斯蒙德斯', '堕天使アスモディウス', 'Token', 'Fairy', NULL, NULL, NULL, NULL, NULL),
(12888461, 'Aspischool', '萨卡班盾鱼群', 'アスピスクール', 'Effect Monster', 'Fish', 'WATER', 4, 300, 300, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡召唤时才能发动。从手卡把1只6星以下的鱼族怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合除外。 ②：这张卡被除外的场合才能发动。这张卡守备表示特殊召唤。'),
(88190790, 'Assault Armor', '强袭气铠', 'アサルト・アーマー', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上的怪兽只有战士族怪兽1只的场合才能给那只怪兽装备。 ①：装备怪兽的攻击力上升300。 ②：把装备的这张卡送去墓地才能发动。这个回合，这张卡装备过的怪兽在同1次的战斗阶段中可以作2次攻击。'),
(3431737, 'Assault Beast', '爆裂兽', 'バスター・ビースト', 'Effect Monster', 'Beast-Warrior', 'EARTH', 4, 1900, 1200, '①：把这张卡从手卡丢弃去墓地才能发动。从卡组把1张「爆裂模式」加入手卡。'),
(23338098, 'Assault Blackwing - Chidori the Rain Sprinkling', '强袭黑羽－泪雨之千鸟', 'A BF－涙雨のチドリ', 'Synchro Monster', 'Winged Beast', 'DARK', 7, 2600, 2000, '调整＋调整以外的怪兽1只以上 ①：「黑羽」怪兽为素材作同调召唤的这张卡当作调整使用。 ②：这张卡的攻击力上升自己墓地的「黑羽」怪兽数量×300。 ③：这张卡被破坏送去墓地时，以「强袭黑羽-泪雨之千鸟刀鸟」以外的自己墓地1只鸟兽族同调怪兽为对象才能发动。那只怪兽特殊召唤。'),
(70456282, 'Assault Blackwing - Kunai the Drizzle', '强袭黑羽-雾雨之苦无鸟', 'A BF－霧雨のクナイ', 'Effect Monster', 'Winged Beast', 'DARK', 5, 2100, 1600, '①：这张卡可以把自己场上1只「黑羽」怪兽解放从手卡特殊召唤。这个方法特殊召唤的这张卡当作调整使用。 ②：1回合1次，以自己场上1只同调怪兽为对象，宣言1～8的任意等级才能发动。那只怪兽直到回合结束时变成宣言的等级。'),
(80773359, 'Assault Blackwing - Onimaru the Divine Thunder', '强袭黑羽－神立之鬼丸', 'A BF－神立のオニマル', 'Synchro Monster', 'Winged Beast', 'DARK', 12, 3000, 2000, '调整＋调整以外的怪兽1只以上 「强袭黑羽-神立之鬼丸刀鸟」的③的效果在决斗中只能使用1次。 ①：「黑羽」怪兽为素材作同调召唤的这张卡当作调整使用。 ②：这张卡不会被效果破坏。 ③：以自己墓地1只「黑羽」怪兽为对象才能发动。这张卡的等级变成和那只怪兽相同。 ④：只用同调怪兽为素材作同调召唤的这张卡攻击的场合，伤害步骤内这张卡的攻击力上升3000。'),
(16051717, 'Assault Blackwing - Raikiri the Rain Shower', '强袭黑羽－骤雨之雷切', 'A BF－驟雨のライキリ', 'Synchro Monster', 'Winged Beast', 'DARK', 7, 2600, 2000, '调整＋调整以外的怪兽1只以上 ①：「黑羽」怪兽为素材作同调召唤的这张卡当作调整使用。 ②：1回合1次，以最多有这张卡以外的自己场上的「黑羽」怪兽数量的对方场上的卡为对象才能发动。那些卡破坏。'),
(17994645, 'Assault Blackwing - Sayo the Rain Hider', '强袭黑羽－雨隐之小夜', 'A BF－雨隠れのサヨ', 'Synchro Monster', 'Winged Beast', 'DARK', 2, 800, 100, '调整＋调整以外的怪兽1只 ①：「黑羽」怪兽为素材作同调召唤的这张卡当作调整使用。 ②：这张卡1回合最多2次不会被战斗破坏。'),
(53389254, 'Assault Blackwing - Sohaya the Rain Storm', '强袭黑羽－五月雨之骚速', 'A BF－五月雨のソハヤ', 'Synchro Monster', 'Winged Beast', 'DARK', 5, 1500, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的②③的效果1回合各能使用1次。 ①：「黑羽」怪兽为素材作同调召唤的这张卡当作调整使用。 ②：这张卡同调召唤成功时，以自己墓地1只「强袭黑羽」怪兽为对象才能发动。那只怪兽特殊召唤。 ③：这张卡被送去墓地的回合的自己主要阶段，从自己墓地把这张卡以外的1只「强袭黑羽-五月雨之骚速刀鸟」除外才能发动。这张卡特殊召唤。'),
(76407432, 'Assault Counter', '爆裂反击', 'バスター・カウンター', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '①：自己场上有「/爆裂体」怪兽存在，怪兽的效果·魔法·陷阱卡发动时才能发动。那个发动无效并破坏。'),
(72714226, 'Assault Dog', '突击枪犬', 'アサルト・ガンドッグ', 'Effect Monster', 'Beast', 'EARTH', 4, 1200, 800, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把「突击枪犬」任意数量特殊召唤。'),
(86098176, 'Assault Lich', '爆裂巫妖', 'バスター・リッチー', 'Tuner Monster', 'Zombie', 'DARK', 4, 1500, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从自己墓地把1只有「爆裂模式」的卡名记述的怪兽或者4星以下的不死族怪兽特殊召唤。 ②：把自己场上的这张卡作为同调素材的场合，可以把这张卡当作调整以外的怪兽使用。 ③：这张卡作为同调素材送去墓地的场合才能发动。从卡组把1张「爆裂斩」或「爆裂反击」加入手卡。'),
(77036039, 'Assault Mercenary', '爆裂佣兵', 'バスター・マーセナリ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1800, 300, '可以让自己的手卡或者墓地存在的1张「爆裂模式」回到卡组，对方场上存在的1张魔法·陷阱卡破坏。这个效果1回合只能使用1次。'),
(80280737, 'Assault Mode Activate', '爆裂模式', 'バスター・モード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把自己场上1只同调怪兽解放才能发动。包含那只怪兽卡名的1只「/爆裂体」怪兽从卡组攻击表示特殊召唤。');